<?php
require_once 'config/database.php';require_once 'includes/functions.php';require_login();
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$conn->prepare('DELETE FROM products WHERE id=?');$s->bind_param('i',$id);$s->execute();flash('Product deleted.');header('Location: products.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$sku=trim($_POST['sku']??'');$cat=(int)($_POST['category_id']??0)?:null;$sup=(int)($_POST['supplier_id']??0)?:null;$cost=(float)($_POST['cost_price']??0);$price=(float)($_POST['selling_price']??0);$qty=(int)($_POST['quantity']??0);$reorder=(int)($_POST['reorder_level']??5);if(!$name||!$sku||$cost<0||$price<0||$qty<0||$reorder<0){flash('Please enter valid product details.','danger');}else{try{if($id){$s=$conn->prepare('UPDATE products SET category_id=?,supplier_id=?,name=?,sku=?,cost_price=?,selling_price=?,quantity=?,reorder_level=? WHERE id=?');$s->bind_param('iissddiii',$cat,$sup,$name,$sku,$cost,$price,$qty,$reorder,$id);}else{$s=$conn->prepare('INSERT INTO products(category_id,supplier_id,name,sku,cost_price,selling_price,quantity,reorder_level) VALUES(?,?,?,?,?,?,?,?)');$s->bind_param('iissddii',$cat,$sup,$name,$sku,$cost,$price,$qty,$reorder);}$s->execute();flash('Product saved successfully.');}catch(Throwable $e){flash('Could not save product. SKU must be unique; check your entries.','danger');}}header('Location: products.php');exit;}
$edit=null;if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$s=$conn->prepare('SELECT * FROM products WHERE id=?');$s->bind_param('i',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}$cats=$conn->query('SELECT id,name FROM categories ORDER BY name')->fetch_all(MYSQLI_ASSOC);$sups=$conn->query('SELECT id,name FROM suppliers ORDER BY name')->fetch_all(MYSQLI_ASSOC);$rows=$conn->query('SELECT p.*,c.name category,s.name supplier FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id ORDER BY p.id DESC');$pageTitle='Products';$active='products';require 'includes/header.php';?>
<div class="card card-primary"><div class="card-header"><h3 class="card-title"><?=$edit?'Edit Product':'Add Product'?></h3></div><form method="post"><div class="card-body"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="row"><div class="col-md-4 form-group"><label>Product Name *</label><input name="name" class="form-control" required value="<?=e($edit['name']??'')?>"></div><div class="col-md-3 form-group"><label>SKU / Code *</label><input name="sku" class="form-control" required value="<?=e($edit['sku']??'')?>"></div><div class="col-md-2 form-group"><label>Category</label><select name="category_id" class="form-control"><option value="">None</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??'')==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-3 form-group"><label>Supplier</label><select name="supplier_id" class="form-control"><option value="">None</option><?php foreach($sups as $s):?><option value="<?=$s['id']?>" <?=($edit['supplier_id']??'')==$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-3 form-group"><label>Cost Price (TZS)</label><input type="number" min="0" step="0.01" name="cost_price" class="form-control" required value="<?=e($edit['cost_price']??'0')?>"></div><div class="col-md-3 form-group"><label>Selling Price (TZS)</label><input type="number" min="0" step="0.01" name="selling_price" class="form-control" required value="<?=e($edit['selling_price']??'0')?>"></div><div class="col-md-3 form-group"><label>Quantity in Stock</label><input type="number" min="0" name="quantity" class="form-control" required value="<?=e($edit['quantity']??'0')?>"></div><div class="col-md-3 form-group"><label>Low-stock level</label><input type="number" min="0" name="reorder_level" class="form-control" value="<?=e($edit['reorder_level']??'5')?>" required></div></div></div><div class="card-footer"><button class="btn btn-primary">Save Product</button> <a href="products.php" class="btn btn-default">Clear</a></div></form></div>
<div class="card"><div class="card-header"><h3 class="card-title">Product Inventory</h3><div class="card-tools"><input id="search" class="form-control form-control-sm" placeholder="Search products"></div></div><div class="card-body table-responsive p-0"><table id="table" class="table table-striped"><thead><tr><th>Name / SKU</th><th>Category</th><th>Supplier</th><th>Cost</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['name'])?><br><small><?=e($r['sku'])?></small></td><td><?=e($r['category']??'-')?></td><td><?=e($r['supplier']??'-')?></td><td><?=money($r['cost_price'])?></td><td><?=money($r['selling_price'])?></td><td><?=$r['quantity']?></td><td><?=$r['quantity']<=$r['reorder_level']?'<span class="badge badge-danger">Low stock</span>':'<span class="badge badge-success">In stock</span>'?></td><td><a class="btn btn-xs btn-info" href="?edit=<?=$r['id']?>">Edit</a> <a class="btn btn-xs btn-danger" onclick="return confirm('Delete this product?')" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></tbody></table></div></div><script>document.getElementById('search').addEventListener('input',function(){let q=this.value.toLowerCase();document.querySelectorAll('#table tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')})</script><?php require 'includes/footer.php';?>
